function validate([s, queries]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 30000) return 's needs 2 to 30000 letters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase English letters.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 30000) return 'queries needs 1 to 30000 entries.';
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 2 || !Number.isInteger(q[0]) || !Number.isInteger(q[1])) return 'Each query is a pair [l, r].';
    if (q[0] < 0 || q[0] > q[1] || q[1] >= s.length) return 'Each query needs 0 <= l <= r < s.length.';
  }
  return null;
}

