function sameEndSubstringCount(s, queries) {
  const n = s.length;
  const prefix = Array.from({ length: 26 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i < n; i++) {
    const letter = s.charCodeAt(i) - 97;
    for (let c = 0; c < 26; c++) {
      prefix[c][i + 1] = prefix[c][i];
    }
    prefix[letter][i + 1]++;
  }

  const answer = [];
  for (const [left, right] of queries) {
    let total = 0;
    for (let c = 0; c < 26; c++) {
      const count = prefix[c][right + 1] - prefix[c][left];
      total += (count * (count + 1)) / 2;
    }
    answer.push(total);
  }
  return answer;
}

