function sameEndSubstringCount(s, queries) {
  return queries.map(([l, r]) => {
    let found = 0;
    for (let i = l; i <= r; i++)
      for (let j = i; j <= r; j++)
        if (s[i] === s[j]) found++;
    return found;
  });
}

