function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? pick(6000, 8000) : pick(2, 10);
  const alphabet = large ? pick(1, 26) : pick(1, 4);
  const s = Array.from({ length: n }, () => String.fromCharCode(97 + pick(0, alphabet - 1))).join('');
  const queries = Array.from({ length: large ? 2000 : pick(1, 6) }, () => {
    const a = pick(0, n - 1), b = pick(0, n - 1);
    return [Math.min(a, b), Math.max(a, b)];
  });
  return [s, queries];
}
